def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 483.4328392742829  # OPT_PARAM: {"initial": 483.4328392742829, "min": 400, "max": 900, "type": "float"}
    order_cap = 87.68905690081193  # OPT_PARAM: {"initial": 87.68905690081193, "min": 50, "max": 300, "type": "float"}
    safety_stock = 148.9425279811676  # OPT_PARAM: {"initial": 148.9425279811676, "min": 10, "max": 150, "type": "float"}
    demand_forecast_factor = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.5, "max": 1.5, "type": "float"}
    pipeline_weight = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.0, "max": 0.5, "type": "float"}
    recent_demand_weight = 0.011983350822311395  # OPT_PARAM: {"initial": 0.011983350822311395, "min": 0.0, "max": 1.0, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Estimate upcoming demand using weighted pipeline arrivals
    if pipeline_orders:
        weighted_sum = sum(p * (pipeline_weight ** i) for i, p in enumerate(reversed(pipeline_orders)))
        weight_sum = sum(pipeline_weight ** i for i in range(len(pipeline_orders)))
        avg_pipeline_arrival = weighted_sum / weight_sum if weight_sum > 0 else 0
    else:
        avg_pipeline_arrival = 0

    # Incorporate recent demand pattern from pipeline
    recent_pipeline = pipeline_orders[-3:] if len(pipeline_orders) >= 3 else pipeline_orders
    if recent_pipeline:
        recent_avg = sum(recent_pipeline) / len(recent_pipeline)
        # Blend historical average with recent trend
        blended_forecast = (1 - recent_demand_weight) * avg_pipeline_arrival + recent_demand_weight * recent_avg
    else:
        blended_forecast = avg_pipeline_arrival

    # Adjust base stock based on demand forecast
    forecast_adjustment = blended_forecast * demand_forecast_factor
    adjusted_base_stock = base_stock + forecast_adjustment

    # Calculate target inventory with safety stock
    target_inventory = adjusted_base_stock + safety_stock

    # Calculate desired order amount
    desired_order = max(0, target_inventory - inventory_position)

    # Apply order cap
    order_amount = min(desired_order, order_cap)

    return order_amount
